from collections import deque

def comps4(g):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); cs=[]
                while q:
                    a,b=q.popleft(); cs.append((a,b))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<R and 0<=y<C and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                out.append((col,cs))
    return out

def canon(cells):
    cells=sorted(cells)
    pts=[(r-min(r for r,_ in cells), c-min(c for _,c in cells)) for r,c in cells]
    best=[]
    for rot in range(4):
        # rotate
        if rot: pts=[(c,-r) for r,c in pts]
        for refl in (False,True):
            p2=[(r,-c) if refl else (r,c) for r,c in pts]
            mr=min(r for r,_ in p2); mc=min(c for _,c in p2)
            p3=sorted((r-mr,c-mc) for r,c in p2)
            best.append(tuple(p3))
    return min(best)

